import React from 'react';
import img4693 from '../images/IMG_4693.JPG';
import Avatar from '@mui/material/Avatar';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';



function Home () {
return(
    <div background-color="#012340" style={{ display: 'flex', justifyContent: 'space-between', height: '100vh'}}>
    <div style={{ width: '50%', display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh'}}>
        <div className='experience' style={{ flex: 1, border: '1px solid black', padding: '20px'}}>
            <List>
                <ListItem> Experience One</ListItem>
                <ListItem> Experience Two</ListItem>
                <ListItem> Experience Three</ListItem>
                <ListItem> Experience Four</ListItem>
            </List>
        </div>
        <div style={{ width: '50%', display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh'}}></div>
         <div className='bio' style={{ flex: 1, border: '1px solid black', padding: '20px'}}>
            <Avatar src={img4693} alt='Paulo Santos' sx={{ width: 100 ,height: 100}} />
            <text> Home </text>
        </div>
    </div>
    </div>

)
}

export default Home;
